function ComingSoonCard({ item, farmerId, onDelete }: { item: Produce; farmerId: string; onDelete?: () => void }) {
  const { tx } = useLang()
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [submitted, setSubmitted] = useState(false)
  const [loading, setLoading] = useState(false)

  const handleNotify = async () => {
    if (!name || !phone) return
    setLoading(true)
    await supabase.from('notify_requests').insert({
      farmer_id: farmerId,
      produce_name: item.name,
      requester_name: name,
      requester_phone: phone,
    })
    setSubmitted(true)
    setLoading(false)
  }

  return (
    <div className="bg-white rounded-xl border-2 border-dashed border-gray-200 p-4">
      <div className="flex items-center justify-between mb-2">
        <div>
          <h3 className="font-bold text-gray-700 text-sm">{item.emoji ?? '🌱'} {item.name}</h3>
          {item.available_to && (
            <p className="text-xs text-gray-500 mt-0.5">
              {tx.expected} {new Date(item.available_to).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}
            </p>
          )}
        </div>
        <span className="bg-amber-100 text-amber-700 text-[10px] font-bold px-2 py-1 rounded-full">
          {tx.comingSoon}
        </span>
      </div>

      {submitted ? (
        <p className="text-sm text-green-700 font-semibold text-center py-2">{tx.notifySuccess}</p>
      ) : (
        <div className="space-y-2 mt-3">
          <input type="text" placeholder={tx.yourName} value={name} onChange={(e) => setName(e.target.value)}
            className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm" />
          <input type="tel" placeholder={tx.yourPhone} value={phone} onChange={(e) => setPhone(e.target.value)}
            className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm" />
          <button onClick={handleNotify} disabled={loading}
            className="w-full bg-amber-600 text-white text-sm font-semibold py-2.5 rounded-lg disabled:opacity-60">
            {loading ? tx.saving : tx.notifyMe}
          </button>
        </div>
      )}

      {onDelete && (
        <button
          onClick={onDelete}
          className="mt-3 w-full border border-red-200 text-red-600 font-semibold py-2.5 rounded-lg text-sm active:bg-red-50"
        >
          🗑 Delete / తొలగించు
        </button>
      )}
    </div>
  )
}

import { supabase } from '@/lib/supabase'
import { NextRequest, NextResponse } from 'next/server'

const CATEGORY_KEYWORDS: Record<string, string[]> = {
  vegetables: [
    'tomato', 'capsicum', 'brinjal', 'eggplant', 'bean', 'pea', 'pumpkin',
    'gourd', 'onion', 'potato', 'garlic', 'carrot', 'radish', 'cucumber',
    'okra', 'ladyfinger', 'drumstick', 'ridge gourd', 'bottle gourd', 'chilli',
    'pepper', 'bitter gourd', 'cluster bean', 'snake gourd',
  ],
  fruits: [
    'mango', 'banana', 'papaya', 'guava', 'pomegranate', 'orange', 'lime',
    'lemon', 'coconut', 'tamarind', 'jackfruit', 'sapota', 'fig', 'grapes',
    'watermelon', 'muskmelon', 'pineapple', 'custard apple',
  ],
  grains: [
    'rice', 'wheat', 'jowar', 'bajra', 'ragi', 'maize', 'corn', 'dal',
    'lentil', 'chickpea', 'groundnut', 'sesame', 'turmeric', 'ginger',
    'pulses', 'toor', 'moong', 'urad', 'chana',
  ],
  leafy: [
    'spinach', 'methi', 'fenugreek', 'coriander', 'mint', 'curry',
    'amaranth', 'sorrel', 'moringa', 'drumstick leaves', 'palak',
  ],
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const q = searchParams.get('q') ?? ''
  const method = searchParams.get('method') ?? ''
  const category = searchParams.get('category') ?? ''

  const { data: produce } = await supabase
    .from('produce_listings')
    .select('*')
    .eq('status', 'available')
    .order('created_at', { ascending: false })

  let filtered = produce ?? []

  if (q) {
    const query = q.toLowerCase()
    filtered = filtered.filter(
      (p) =>
        p.name?.toLowerCase().includes(query) ||
        p.variety?.toLowerCase().includes(query) ||
        p.description?.toLowerCase().includes(query)
    )
  }

  if (method && method !== 'all') {
    filtered = filtered.filter((p) =>
      p.method?.toLowerCase().includes(method.toLowerCase())
    )
  }

  if (category && category !== 'all' && CATEGORY_KEYWORDS[category]) {
    const keywords = CATEGORY_KEYWORDS[category]
    filtered = filtered.filter((p) =>
      keywords.some((kw) => p.name?.toLowerCase().includes(kw))
    )
  }

  if (!filtered.length) return NextResponse.json([])

  const farmerIds = [...new Set(filtered.map((p) => p.farmer_id))]

  const { data: farmers } = await supabase
    .from('farmers')
    .select('id, name, village, slug, phone, method, pickup_locations')
    .in('id', farmerIds)
    .eq('active', true)

  const farmerMap = Object.fromEntries((farmers ?? []).map((f) => [f.id, f]))

  const result = filtered
    .map((p) => ({ ...p, farmer: farmerMap[p.farmer_id] ?? null }))
    .filter((p) => p.farmer !== null)

  return NextResponse.json(result)
}

